solution.solution.cpp:
#include <optional>
#include <string>

struct Flags { bool zf, sf, cf, of; };

std::optional<bool> taken(const std::string& condition, Flags f)
{
    if (condition == "e" || condition == "z") return f.zf;
    if (condition == "ne" || condition == "nz") return !f.zf;
    if (condition == "l") return f.sf != f.of;
    if (condition == "le") return f.zf || f.sf != f.of;
    if (condition == "g") return !f.zf && f.sf == f.of;
    if (condition == "ge") return f.sf == f.of;
    if (condition == "b") return f.cf;
    if (condition == "be") return f.cf || f.zf;
    if (condition == "a") return !f.cf && !f.zf;
    if (condition == "ae") return !f.cf;
    if (condition == "s") return f.sf;
    if (condition == "ns") return !f.sf;
    return std::nullopt;
}

unitTests:
const Flags less{ false, true, true, false };      // cmp 3, 5
const Flags equal{ true, false, false, false };    // cmp 5, 5
const Flags minusOneVsOne{ false, true, false, false };   // cmp -1, 1: signed less, unsigned above
TEST("three is less than five") { CHECK(*taken("l", less)); CHECK(*taken("b", less)); CHECK(!*taken("g", less)); CHECK(!*taken("ae", less)); }
TEST("equal") { CHECK(*taken("e", equal)); CHECK(*taken("z", equal)); CHECK(*taken("le", equal)); CHECK(*taken("ge", equal)); CHECK(!*taken("ne", equal)); CHECK(*taken("be", equal)); CHECK(!*taken("a", equal)); }
TEST("signed and unsigned disagree") { CHECK(*taken("l", minusOneVsOne)); CHECK(*taken("a", minusOneVsOne)); CHECK(!*taken("b", minusOneVsOne)); }
TEST("signed overflow case") { const Flags f{ false, false, false, true }; CHECK(*taken("l", f)); CHECK(!*taken("ge", f)); }
TEST("sign conditions") { CHECK(*taken("s", less)); CHECK(*taken("ns", equal)); }
TEST("unknown") { CHECK(!taken("q", less).has_value()); CHECK(!taken("", less).has_value()); }

